patch:
--- a/src/billing/index.js
+++ b/src/billing/index.js
@@ -1,1 +1,2 @@
-module.exports = {};
+const rate = require("src/billing/internal/rate.js");
+module.exports = { tax: (amount) => rate(amount) };
--- a/src/checkout/total.js
+++ b/src/checkout/total.js
@@ -1,2 +1,2 @@
-const rate = require("src/billing/internal/rate.js");
-module.exports = (amount) => amount + rate(amount);
+const { tax } = require("src/billing/index.js");
+module.exports = (amount) => amount + tax(amount);

